#include <print>

int main() {
    int score = 95;

    if (score >= 90) {
        std::println("{} 分：优秀", score);
    } else if (score >= 80) {
        std::println("{} 分：良好", score);
    } else if (score >= 60) {
        std::println("{} 分：及格", score);
    } else {
        std::println("{} 分：不及格", score);
    }

    int trial = 85;
    if (trial >= 60) {
        std::println("{} 分：及格", trial);
    } else if (trial >= 90) {
        std::println("{} 分：优秀", trial);
    }
    // 85 被打成及格，>=90 那一档再也走不到

    return 0;
}

